from pyspark.sql import SparkSession, DataFrame
from pyspark.sql.types import StructType, StructField, IntegerType, StringType

# Initialize Spark session
spark = SparkSession.builder.appName("NationData").getOrCreate()

def get_nation_data(spark, parameters: dict) -> DataFrame:

    # Extract parameters from YAML configuration
    batch_size = parameters.get("batch_size", 1000)
    start_date = parameters.get("start_date", "2023-01-01")

    # Define schema
    schema = StructType([
        StructField("n_nationkey", IntegerType(), True),
        StructField("n_name", StringType(), True),
        StructField("n_regionkey", IntegerType(), True),
        StructField("n_comment", StringType(), True)
    ])

    # Create sample data
    data = [
        (0, "ALGERIA", 0, "haggle. carefully final deposits detect slyly agai"),
        (1, "ARGENTINA", 1, "al foxes promise slyly according to the regular accounts. bold requests alon"),
        (2, "BRAZIL", 1, "y alongside of the pending deposits. carefully special packages are about the ironic forges. slyly special"),
        (3, "CANADA", 1, "eas hang ironic, silent packages. slyly regular packages are furiously over the tithes. fluffily bold"),
        (4, "EGYPT", 4, "y above the carefully unusual theodolites. final dugouts are quickly across the furiously regular d"),
    ]

    # Create DataFrame
    nation_df = spark.createDataFrame(data, schema)

    # Return the DataFrame
    return nation_df
